import { pt, enUS } from 'date-fns/locale';
import { getTranslateLabel, getTranslationsDate } from './utils';

describe('utils', () => {
  it('Should return the en file when the language is not passed', () => {
    const result = getTranslationsDate();

    expect(result).toEqual(enUS);
  });

  it('Should return the file to correct language', () => {
    const result = getTranslationsDate('pt');

    expect(result).toEqual(pt);
  });

  it('Should return label with default language when the language is not passed', () => {
    const result = getTranslateLabel('to');

    expect(result).toEqual('to');
  });

  it('Should return the translate correct to each language', () => {
    const resultEN = getTranslateLabel('to', 'en');
    const resultPT = getTranslateLabel('to', 'pt');
    const resultES = getTranslateLabel('to', 'es');

    expect(resultEN).toEqual('to');
    expect(resultPT).toEqual('a');
    expect(resultES).toEqual('al');
  });
});
